import React, { useEffect, useMemo, useRef, useState } from 'react';
import { casesAPI, openingsAPI } from '../services/api';
import ImageWithFallback from './ImageWithFallback';
import './CaseOpeningAnimation.css';

const SLOT_WIDTH = 140;
const WINNER_INDEX = 36;
const TOTAL_SLOTS = 52;
const ANIMATION_MS = 5600;

const CaseOpeningAnimation = ({ caseId, onComplete, onClose }) => {
  const [caseData, setCaseData] = useState(null);
  const [openingResult, setOpeningResult] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [animating, setAnimating] = useState(false);
  const [finished, setFinished] = useState(false);
  const [translateX, setTranslateX] = useState(0);
  const viewportRef = useRef(null);
  const completedRef = useRef(false);

  useEffect(() => {
    let cancelled = false;

    const load = async () => {
      setLoading(true);
      setError('');
      try {
        const [caseResponse, openingResponse] = await Promise.all([
          casesAPI.getCaseById(caseId),
          openingsAPI.openCase(caseId),
        ]);
        if (!cancelled) {
          setCaseData(caseResponse.data);
          setOpeningResult(openingResponse.data);
        }
      } catch (err) {
        console.error('Error in case opening:', err);
        if (!cancelled) {
          setError(err.response?.data?.detail || 'Unable to open this case.');
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    if (caseId) load();
    return () => {
      cancelled = true;
    };
  }, [caseId]);

  const wonItem = useMemo(() => {
    if (!caseData || !openingResult) return null;
    return (
      caseData.items.find((item) => item.id === openingResult.item_id) ||
      openingResult.item ||
      null
    );
  }, [caseData, openingResult]);

  const sequence = useMemo(() => {
    if (!caseData?.items?.length || !wonItem) return [];

    const items = caseData.items;
    const result = [];
    for (let index = 0; index < TOTAL_SLOTS; index += 1) {
      if (index === WINNER_INDEX) {
        result.push(wonItem);
        continue;
      }

      let candidate = items[Math.floor(Math.random() * items.length)];
      if (items.length > 1 && candidate.id === wonItem.id) {
        candidate = items.find((item) => item.id !== wonItem.id) || candidate;
      }
      result.push(candidate);
    }
    return result;
  }, [caseData, wonItem]);

  useEffect(() => {
    if (!sequence.length || !wonItem || animating || finished) return undefined;

    const viewportWidth = viewportRef.current?.clientWidth || 760;
    const winnerCenter = WINNER_INDEX * SLOT_WIDTH + SLOT_WIDTH / 2;
    const target = Math.round(viewportWidth / 2 - winnerCenter);

    setTranslateX(0);
    const startTimer = window.setTimeout(() => {
      setAnimating(true);
      requestAnimationFrame(() => setTranslateX(target));
    }, 450);

    const finishTimer = window.setTimeout(() => {
      setAnimating(false);
      setFinished(true);
      if (!completedRef.current) {
        completedRef.current = true;
        onComplete?.(wonItem);
      }
    }, 450 + ANIMATION_MS);

    return () => {
      window.clearTimeout(startTimer);
      window.clearTimeout(finishTimer);
    };
  }, [sequence, wonItem, animating, finished, onComplete]);

  if (loading) {
    return (
      <div className="opening-animation-container opening-state">
        <div className="spinner-border text-primary" role="status" />
        <p className="mt-3 mb-0">Opening {caseData?.name || 'case'}…</p>
      </div>
    );
  }

  if (error || !caseData || !wonItem) {
    return (
      <div className="opening-animation-container opening-state">
        <h4>Opening failed</h4>
        <p className="text-muted">{error || 'The opening result is incomplete.'}</p>
        <button className="btn btn-outline-light" onClick={onClose}>Close</button>
      </div>
    );
  }

  const getRarityClass = (rarity) =>
    rarity ? `rarity-${rarity.toLowerCase().replace(/\s+/g, '-')}` : 'rarity-default';

  return (
    <div className={`opening-animation-container ${animating ? 'is-animating' : ''} ${finished ? 'is-finished' : ''}`}>
      <div className="opening-header">
        <h3>Opening {caseData.name}</h3>
        <p>Case price: {caseData.price.toLocaleString()} €</p>
      </div>

      <div className="opening-viewport" ref={viewportRef}>
        <div className="opening-pointer" aria-hidden="true" />
        <div
          className="opening-track"
          style={{
            width: `${sequence.length * SLOT_WIDTH}px`,
            transform: `translate3d(${translateX}px, 0, 0)`,
          }}
        >
          {sequence.map((item, index) => (
            <div
              className={`opening-slide-item ${index === WINNER_INDEX ? 'winner-slot' : ''}`}
              key={`${item.id}-${index}`}
              style={{ width: `${SLOT_WIDTH}px` }}
            >
              <div className="opening-item-card">
                <ImageWithFallback
                  src={item.image_url}
                  alt={item.name}
                  className="item-image"
                  style={{ width: '92px', height: '92px', objectFit: 'contain' }}
                />
                <div className="item-name" title={item.name}>{item.name}</div>
                <div className={`item-rarity ${getRarityClass(item.rarity)}`}>
                  {item.rarity}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="opening-status" aria-live="polite">
        {finished ? (
          <>
            <span className="status-label">You won</span>
            <strong>{wonItem.name}</strong>
          </>
        ) : (
          <span>{animating ? 'Rolling…' : 'Preparing the roll…'}</span>
        )}
      </div>

      {finished && (
        <div className="won-item-display">
          <ImageWithFallback
            src={wonItem.image_url}
            alt={wonItem.name}
            className="won-item-image"
            style={{ width: '130px', height: '130px', objectFit: 'contain' }}
          />
          <div className="won-item-name">{wonItem.name}</div>
          <div className={`won-item-rarity ${getRarityClass(wonItem.rarity)}`}>
            {wonItem.rarity} · {Number(wonItem.virtual_value).toLocaleString()} €
          </div>
          <button className="btn btn-primary mt-3" onClick={onClose}>Continue</button>
        </div>
      )}
    </div>
  );
};

export default CaseOpeningAnimation;
